import {
  IsIn,
  IsNotEmpty,
  IsOptional,
  IsString,
  Matches,
  MaxLength,
} from 'class-validator';
import {
  PUBLIC_LOCALES,
  type PublicLocale,
} from '../../../common/i18n/locale.js';
import {
  SLUG_MAX_LENGTH,
  SLUG_MESSAGE,
  SLUG_PATTERN,
} from '../../../common/slug.js';
import { Trim } from '../../../common/validation/transforms.js';

export const CHAT_MESSAGE_MAX = 1000;
/** cuid ids are lowercase letters and digits. */
const CONVERSATION_ID = /^[a-z0-9]{10,40}$/;
/** Random id generated by the browser (e.g. crypto.randomUUID()). */
const VISITOR_ID = /^[A-Za-z0-9_-]{8,64}$/;

/** `POST /assistant/chat` */
export class ChatRequestDto {
  /** Omit (or null) to start a conversation; the `conversation` event returns its id. */
  @IsOptional()
  @IsString()
  @Matches(CONVERSATION_ID, { message: 'conversationId no es válido' })
  conversationId?: string | null;

  @IsString()
  @Matches(VISITOR_ID, {
    message: 'visitorId debe tener de 8 a 64 caracteres (letras, números, - o _)',
  })
  visitorId: string;

  @IsIn(PUBLIC_LOCALES, { message: 'locale debe ser "es" o "en"' })
  locale: PublicLocale;

  @Trim()
  @IsString()
  @IsNotEmpty({ message: 'message no debe estar vacío' })
  @MaxLength(CHAT_MESSAGE_MAX, {
    message: `message admite como máximo ${CHAT_MESSAGE_MAX} caracteres`,
  })
  message: string;

  /** Slug (in `locale`) of the case page the chat is embedded in. */
  @IsOptional()
  @IsString()
  @MaxLength(SLUG_MAX_LENGTH)
  @Matches(SLUG_PATTERN, { message: SLUG_MESSAGE })
  caseSlug?: string | null;
}

/** `POST /admin/assistant/test` ("Probar pregunta sobre este caso"). */
export class AssistantTestDto {
  @Trim()
  @IsString()
  @IsNotEmpty({ message: 'question no debe estar vacía' })
  @MaxLength(CHAT_MESSAGE_MAX)
  question: string;

  @IsIn(PUBLIC_LOCALES, { message: 'locale debe ser "es" o "en"' })
  locale: PublicLocale;

  @IsOptional()
  @IsString()
  @MaxLength(SLUG_MAX_LENGTH)
  @Matches(SLUG_PATTERN, { message: SLUG_MESSAGE })
  caseSlug?: string | null;
}
